<!-- LONG ROLE FORMS --><term name="author"/> <!-- generally blank --><term name="chair"><single>chair</single><multiple>chairs</multiple></term><term name="collection-editor"><single>ed.</single><multiple>eds.</multiple></term><term name="compiler"><single>compiler</single><multiple>compilers</multiple></term><term name="composer"/> <!-- generally blank --><term name="container-author"/> <!-- generally blank --><term name="contributor"><single>contributor</single><multiple>contributors</multiple></term><term name="curator"><single>curator</single><multiple>curators</multiple></term><term name="director"><single>director</single><multiple>directores</multiple></term><term name="editor"><single>editor</single><multiple>editores</multiple></term><term name="editor-translator"><single>editor y traductor</single><multiple>editores y traductores</multiple></term><term name="editortranslator"><single>editor y traductor</single><multiple>editores y traductores</multiple></term><term name="editorial-director"><single>editor</single><multiple>editores</multiple></term><term name="executive-producer"><single>executive producer</single><multiple>executive producers</multiple></term><term name="guest"><single>guest</single><multiple>guests</multiple></term><term name="host"><single>host</single><multiple>hosts</multiple></term><term name="illustrator"><single>ilustrador</single><multiple>ilustradores</multiple></term><term name="interviewer"/> <!-- generally blank --><term name="narrator"><single>narrator</single><multiple>narrators</multiple></term><term name="organizer"><single>organizer</single><multiple>organizers</multiple></term><term name="original-author"/> <!-- generally blank --><term name="performer"><single>performer</single><multiple>performers</multiple></term><term name="producer"><single>producer</single><multiple>producers</multiple></term><term name="recipient"/> <!-- generally blank --><term name="reviewed-author"/> <!-- generally blank --><term name="script-writer"><single>writer</single><multiple>writers</multiple></term><term name="series-creator"><single>series creator</single><multiple>series creators</multiple></term><term name="translator"><single>traductor</single><multiple>traductores</multiple></term>
<!-- SHORT ROLE FORMS --><term name="compiler" form="short"><single>comp.</single><multiple>comps.</multiple></term><term name="contributor" form="short"><single>contrib.</single><multiple>contribs.</multiple></term><term name="curator" form="short"><single>cur.</single><multiple>curs.</multiple></term><term name="director" form="short"><single>dir.</single><multiple>dirs.</multiple></term><term name="editor" form="short"><single>ed.</single><multiple>eds.</multiple></term><term name="editor-translator" form="short"><single>ed. y trad.</single><multiple>eds. y trads.</multiple></term><term name="editortranslator" form="short"><single>ed. y trad.</single><multiple>eds. y trads.</multiple></term><term name="editorial-director" form="short"><single>ed.</single><multiple>eds.</multiple></term><term name="executive-producer" form="short"><single>exec. prod.</single><multiple>exec. prods.</multiple></term><term name="illustrator" form="short"><single>ilust.</single><multiple>ilusts.</multiple></term><term name="narrator" form="short"><single>narr.</single><multiple>narrs.</multiple></term><term name="organizer" form="short"><single>org.</single><multiple>orgs.</multiple></term><term name="performer" form="short"><single>perf.</single><multiple>perfs.</multiple></term><term name="producer" form="short"><single>prod.</single><multiple>prods.</multiple></term><term name="script-writer" form="short"><single>writ.</single><multiple>writs.</multiple></term><term name="series-creator" form="short"><single>cre.</single><multiple>cres.</multiple></term><term name="translator" form="short"><single>trad.</single><multiple>trads.</multiple></term>
<!-- VERB ROLE FORMS --><term name="chair" form="verb">chaired by</term><term name="collection-editor" form="verb">edited by</term><term name="compiler" form="verb">compiled by</term><term name="container-author" form="verb">de</term><term name="contributor" form="verb">with</term><term name="curator" form="verb">curated by</term><term name="director" form="verb">dirigido por</term><term name="editor" form="verb">editado por</term><term name="editor-translator" form="verb">editado y traducido por</term><term name="editortranslator" form="verb">editado y traducido por</term><term name="editorial-director" form="verb">editado por</term><term name="executive-producer" form="verb">executive produced by</term><term name="guest" form="verb">with guest</term><term name="host" form="verb">hosted by</term><term name="illustrator" form="verb">ilustrado por</term><term name="interviewer" form="verb">entrevistado por</term><term name="narrator" form="verb">narrated by</term><term name="organizer" form="verb">organized by</term><term name="performer" form="verb">performed by</term><term name="producer" form="verb">produced by</term><term name="recipient" form="verb">a</term><term name="reviewed-author" form="verb">por</term><term name="script-writer" form="verb">written by</term><term name="series-creator" form="verb">created by</term><term name="translator" form="verb">traducido por</term>
<!-- SHORT VERB ROLE FORMS --><term name="collection-editor" form="verb-short">ed. by</term><term name="compiler" form="verb-short">comp. by</term><term name="contributor" form="verb-short">w.</term><term name="curator" form="verb-short">cur. by</term><term name="director" form="verb-short">dir.</term><term name="editor" form="verb-short">ed.</term><term name="editor-translator" form="verb-short">ed. y trad.</term><term name="editortranslator" form="verb-short">ed. y trad.</term><term name="editorial-director" form="verb-short">ed.</term><term name="executive-producer" form="verb-short">exec. prod. by</term><term name="guest" form="verb-short">w. guest</term><term name="host" form="verb-short">hosted by</term><term name="illustrator" form="verb-short">ilust.</term><term name="narrator" form="verb-short">narr. by</term><term name="organizer" form="verb-short">org. by</term><term name="performer" form="verb-short">perf. by</term><term name="producer" form="verb-short">prod. by</term><term name="script-writer" form="verb-short">writ. by</term><term name="series-creator" form="verb-short">cre. by</term><term name="translator" form="verb-short">trad.</term>
